// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint256 amount, uint256 unlockTime) public {
        vm.assume(amount <= VALUE_CAP);
        // WIDE admissible domain: positive amount within typical funding, future unlock time.
        amount = bound(amount, 1 ether, 100 ether);
        unlockTime = bound(unlockTime, block.timestamp + 1, block.timestamp + 1000);

        address actor = address(0xA11CE);

        // Give the actor enough ETH to deposit and then collect a positive amount.
        vm.deal(actor, amount * 2);

        // Actor deposits, locking in unlockTime. Must be in the future for Collect to pass.
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // Advance past the unlock time so the Collect guard succeeds.
        vm.warp(unlockTime + 1);

        // Record balance before the collect: this must be reduced by exactly `amount` in P.
        ( , uint256 balBefore) = c.Acc(actor);

        vm.prank(actor);
        c.Collect(amount);

        ( , uint256 balAfter) = c.Acc(actor);

        // General rule: a successful Collect of `amount` reduces the caller's stored balance by exactly `amount`.
        // The buggy version (post-call balance update deleted) leaves `balAfter == balBefore`.
        assertTrue(balAfter == balBefore - amount, "collect must reduce caller balance by the collected amount");
    }
}
